css:
/* Hudson County Motors — site-wide design layer.
   Brand colours, fonts, type sizes and radii live in the design system (site/tokens.json).
   The handoff has a few more navy tones than the design system's eight colour slots;
   they are declared once here and used by name everywhere else. */
:root {
  --hcm-body: #41506A;        /* body copy (handoff --ink-600) */
  --hcm-placeholder: #7A8699; /* input placeholder (--ink-400) */
  --hcm-on-navy: #C4CEDC;     /* body copy on navy */
  --hcm-on-navy-2: #A7B4C8;   /* secondary on navy */
  --hcm-on-navy-3: #7A8FAD;   /* tertiary on dark navy */
  --hcm-nav-link: #E8EDF4;    /* nav links */
  --hcm-tint: #E4E9F0;        /* pre-owned badge, tints */
  --hcm-focus: #4D8EFF;
  --hcm-shadow: 0 8px 28px rgb(18 41 74 / 8%);
  --hcm-ease: cubic-bezier(.22, .61, .36, 1);
  --hcm-dur: 180ms;
  --hcm-section-gap: clamp(48px, 8vw, 80px);
  --hcm-grid-gap: 14px;
  --hcm-gutter: var(--container-pad);
}
@media (max-width: 1100px) { :root { --hcm-gutter: var(--container-pad-tablet); } }
@media (max-width: 640px) { :root { --hcm-gutter: var(--container-pad-mobile); } }

body { color: var(--hcm-body); overflow-x: hidden; }
a { transition: color var(--hcm-dur) var(--hcm-ease); }

/* Headings: Barlow Condensed, uppercase, navy. */
.bz-block :is(h1, h2, h3, h4) { font-family: var(--font-heading); font-weight: 700; text-transform: uppercase; color: var(--ink); letter-spacing: 0; }
.bz-block h1 { font-size: clamp(36px, 6vw, var(--text-h1)); line-height: 1; text-wrap: balance; margin: 0; }
.bz-block h2 { font-size: clamp(26px, 4vw, var(--text-h2)); line-height: 1.1; margin: 0 0 24px; }
.bz-block h3 { font-size: var(--text-h3); line-height: 1.1; }
.bz-block p { color: inherit; }

/* Eyebrow: a 26×4 tick and a tracked condensed label. */
.bz-eyebrow { display: flex; align-items: center; gap: 12px; margin: 0 0 18px; font: 600 clamp(13px, 1.6vw, var(--text-eyebrow))/1.2 var(--font-heading); letter-spacing: .22em; text-transform: uppercase; color: var(--muted); }
.bz-eyebrow::before { content: ""; width: 26px; height: 4px; background: var(--accent); flex: none; }

/* Buttons */
.bz-btns { gap: 16px; }
.bz-btn { font: 700 19px/1.2 var(--font-heading); letter-spacing: .06em; text-transform: uppercase; border-radius: var(--radius-input); padding: 16px 34px; border: 2px solid var(--accent); transition: background var(--hcm-dur) var(--hcm-ease), color var(--hcm-dur) var(--hcm-ease), border-color var(--hcm-dur) var(--hcm-ease), transform 120ms var(--hcm-ease); }
.bz-btn:active { transform: scale(.97); }
.bz-btn--primary { background: var(--accent); border-color: var(--accent); color: #fff; }
.bz-btn--primary:hover { background: var(--accent-dark); border-color: var(--accent-dark); color: #fff; }
.bz-btn--secondary { background: transparent; border-color: var(--accent); color: var(--accent); padding: 14px 34px; }
.bz-btn--secondary:hover { background: var(--accent); border-color: var(--accent); color: #fff; }
.bz-btn--link { background: none; border: 0; border-bottom: 2px solid currentColor; border-radius: 0; padding: 0 0 2px; font-weight: 600; font-size: 17px; text-decoration: none; color: var(--accent); }
.bz-btn--link:hover { color: var(--accent-dark); }

/* Focus is always visible. */
a:focus-visible, button:focus-visible, .bz-block a:focus-visible, .bz-block button:focus-visible { outline: 2px solid var(--hcm-focus); outline-offset: 2px; }

/* Inputs */
.bz-input { background: var(--paper); border: 1px solid var(--line); border-radius: var(--radius-input); color: var(--ink-dark); font: 15px var(--font-body); padding: 14px 16px; transition: border-color var(--hcm-dur), box-shadow var(--hcm-dur); }
.bz-input::placeholder { color: var(--hcm-placeholder); }
.bz-input:focus, .bz-input:focus-visible { outline: none; border-color: var(--accent); box-shadow: 0 0 0 3px rgb(24 71 134 / 15%); background: #fff; }

/* Cards: white, hairline, 6px; link cards lift and their photo eases in. */
.bz-card, .bz-quote { background: var(--card); border: 1px solid var(--line); border-radius: var(--radius-card); overflow: hidden; }
a.bz-card { transition: box-shadow var(--hcm-dur) var(--hcm-ease), transform var(--hcm-dur) var(--hcm-ease); }
a.bz-card:hover { box-shadow: var(--hcm-shadow); transform: translateY(-3px); color: inherit; }
.bz-card img { transition: transform 380ms var(--hcm-ease); }
a.bz-card:hover img { transform: scale(1.04); }
@media (prefers-reduced-motion: reduce) { a.bz-card:hover, a.bz-card:hover img { transform: none; } }

/* Layout rhythm. The design spaces blocks with its own margins, and runs every band
   on one fluid gutter (the design system's container padding at each width). */
.bz-block, .bz-block + .bz-block { padding-block: 0; }
.bz-section > .bz-container { padding-inline: var(--hcm-gutter); }
@media (max-width: 640px) {
  .bz-section > .bz-container.bz-container--bleed-left,
  .bz-section > .bz-container.bz-container--bleed-right { padding-inline: var(--hcm-gutter); }
}

/* A photo column beside copy fills the column's height, whatever the photo's shape. */
[data-bz-node$="-media"] { position: relative; min-height: 260px; }
[data-bz-node$="-media"] > .bz-block--image, [data-bz-node$="-media"] .bz-figure { position: absolute; inset: 0; margin: 0; }
[data-bz-node$="-media"] .bz-container { height: 100%; }
[data-bz-node$="-media"] img { width: 100%; height: 100%; object-fit: cover; border-radius: 0; }

/* Logos and menu items size to their content, not to the body line-height. */
.bz-block--logo { display: flex; line-height: 0; }
.bz-navitem { line-height: 1.15; }
